fn smallest_change(arr: Vec<i8>) -> usize {
    let n = arr.len();
    // For empty or length 1 arrays, no changes needed.
    if n <= 1 {
        return 0;
    }

    // Count how many pairs (arr[i], arr[n-1-i]) differ.
    let mut diff_count = 0;
    for i in 0..(n / 2) {
        if arr[i] != arr[n - 1 - i] {
            diff_count += 1;
        }
    }

    diff_count
}